use alloc::borrow::Cow;
use alloc::string::String;

use crate::TypeDef;

/// A static description of one column in a table.
///
/// Generated by `#[derive(Table)]` into the table's [`TableDef`], and consumed by schema
/// generation, migration diffing and introspection.
#[derive(Debug, Clone, PartialEq)]
pub struct ColumnDef {
    /// The column name exactly as it appears in SQL.
    pub name: &'static str,
    /// The canonical type of the column.
    pub ty: TypeDef,
    /// Whether the column accepts `NULL`.
    pub nullable: bool,
    /// Whether the database generates the value (`SERIAL`, `AUTO_INCREMENT`, ...).
    pub auto_increment: bool,
    /// Whether the column is part of the primary key.
    pub primary_key: bool,
    /// Whether the column has a `UNIQUE` constraint of its own.
    pub unique: bool,
    /// A literal default value, rendered by each dialect.
    pub default: Option<DefaultValue>,
}

/// A column default, kept in a form each dialect can render.
#[derive(Debug, Clone, Copy, PartialEq)]
#[non_exhaustive]
pub enum DefaultValue {
    /// `DEFAULT NULL` (or, equivalently, no default).
    Null,
    /// A boolean literal.
    Bool(bool),
    /// An integer literal.
    Int(i64),
    /// A float literal.
    Float(f64),
    /// A string literal.
    Text(&'static str),
    /// A raw SQL expression, inserted verbatim. This is the escape hatch and is unchecked.
    Raw(&'static str),
    /// `CURRENT_TIMESTAMP`.
    Now,
}

impl DefaultValue {
    /// Render the literal part of the default. Raw values pass through untouched.
    pub fn render(&self) -> Cow<'static, str> {
        match self {
            Self::Null => Cow::Borrowed("NULL"),
            Self::Bool(true) => Cow::Borrowed("TRUE"),
            Self::Bool(false) => Cow::Borrowed("FALSE"),
            Self::Int(v) => Cow::Owned(alloc::format!("{v}")),
            Self::Float(v) => Cow::Owned(alloc::format!("{v}")),
            Self::Text(v) => Cow::Owned(alloc::format!("'{}'", v.replace('\'', "''"))),
            Self::Raw(v) => Cow::Borrowed(v),
            Self::Now => Cow::Borrowed("CURRENT_TIMESTAMP"),
        }
    }
}

/// A secondary index declaration.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Index {
    /// The index name.
    pub name: &'static str,
    /// The columns the index covers, in order.
    pub columns: &'static [&'static str],
    /// Whether the index enforces uniqueness.
    pub unique: bool,
}

/// A foreign key constraint.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct ForeignKey {
    /// The constraint name.
    pub name: &'static str,
    /// Columns on this table.
    pub columns: &'static [&'static str],
    /// The table being referenced.
    pub references_table: &'static str,
    /// Columns on the referenced table.
    pub references_columns: &'static [&'static str],
    /// What to do when the referenced row is deleted.
    pub on_delete: ReferenceAction,
    /// What to do when the referenced row is updated.
    pub on_update: ReferenceAction,
}

/// The action taken by a foreign key when the referenced row changes.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default, serde::Serialize, serde::Deserialize)]
#[non_exhaustive]
pub enum ReferenceAction {
    /// Let the database decide (usually `NO ACTION`).
    #[default]
    Default,
    /// `CASCADE`
    Cascade,
    /// `SET NULL`
    SetNull,
    /// `SET DEFAULT`
    SetDefault,
    /// `RESTRICT`
    Restrict,
    /// `NO ACTION`
    NoAction,
}

impl ReferenceAction {
    /// Render the action for a DDL statement.
    pub const fn as_sql(&self) -> Option<&'static str> {
        match self {
            Self::Default => None,
            Self::Cascade => Some("CASCADE"),
            Self::SetNull => Some("SET NULL"),
            Self::SetDefault => Some("SET DEFAULT"),
            Self::Restrict => Some("RESTRICT"),
            Self::NoAction => Some("NO ACTION"),
        }
    }
}

/// The static description of a table, produced by `#[derive(Table)]`.
///
/// This is the metadata the whole system is built on: query builders read the column list
/// from it, migrations diff it against a live database, and the CLI turns it back into
/// Rust code.
#[derive(Debug, Clone, PartialEq)]
pub struct TableDef {
    /// The table name exactly as it appears in SQL.
    pub name: &'static str,
    /// An optional schema or database namespace.
    ///
    /// Every dialect qualifies the name when this is set; PostgreSQL calls it a schema and
    /// MySQL calls it a database. SQLite attached databases work the same way, but SQLite
    /// itself ignores the distinction for a normal file.
    pub schema: Option<&'static str>,
    /// Every column, in the order the model's fields are declared. This ordering is
    /// load-bearing: `SELECT` lists and row decoding both follow it.
    pub columns: &'static [ColumnDef],
    /// Secondary indexes.
    pub indexes: &'static [Index],
    /// Foreign keys.
    pub foreign_keys: &'static [ForeignKey],
}

impl TableDef {
    /// The primary key columns, in declaration order.
    pub fn primary_key(&self) -> impl Iterator<Item = &ColumnDef> {
        self.columns.iter().filter(|c| c.primary_key)
    }

    /// Whether the table has a composite primary key.
    pub fn has_composite_primary_key(&self) -> bool {
        self.columns.iter().filter(|c| c.primary_key).count() > 1
    }

    /// Look up a column by SQL name.
    pub fn column(&self, name: &str) -> Option<&ColumnDef> {
        self.columns.iter().find(|c| c.name == name)
    }

    /// The `SELECT` list for the whole table, unqualified and comma separated.
    pub fn projection(&self) -> String {
        let mut out = String::new();
        for (i, column) in self.columns.iter().enumerate() {
            if i != 0 {
                out.push_str(", ");
            }
            out.push_str(column.name);
        }
        out
    }
}
